<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require_login();$date=(string)($_GET['date']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');$rows=[];$error='';try{$s=db()->prepare('SELECT process_key,COUNT(*) records,SUM(planned_qty) planned,SUM(actual_qty) actual FROM dbo.web_production_plan WHERE plan_date=? GROUP BY process_key');$s->execute([$date]);$by=[];foreach($s->fetchAll() as $r)$by[$r['process_key']]=$r;foreach(PROCESS_LIST as $k=>$p){$r=$by[$k]??[];$rows[]=['key'=>$k,'label'=>$p['label'],'records'=>(int)($r['records']??0),'planned'=>(int)($r['planned']??0),'actual'=>(int)($r['actual']??0)];}}catch(Throwable $e){$error=$e->getMessage();}$planned=array_sum(array_column($rows,'planned'));$actual=array_sum(array_column($rows,'actual'));$rate=$planned?min(100,round($actual/$planned*100)):0;?><?php $pageTitle='Production Dashboard'; $activePage='dashboard'; require __DIR__.'/includes/header.php'; ?><section class="content"><div class="page-intro"><div><h2>Production overview</h2><p>Daily plan vs actual across all processes.</p></div><form><input type="date" name="date" value="<?=h($date)?>" onchange="this.form.submit()"></form></div><?php if($error):?><div class="notice notice-error"><?=h($error)?></div><?php endif;?><div class="stats-grid stats-grid-csv"><article class="stat-card"><span>Planned</span><div class="stat-value"><?=number_format($planned)?></div></article><article class="stat-card"><span>Actual</span><div class="stat-value"><?=number_format($actual)?></div></article><article class="stat-card"><span>Remaining</span><div class="stat-value"><?=number_format(max(0,$planned-$actual))?></div></article><article class="stat-card"><span>Achievement Rate</span><div class="stat-value"><?=$rate?>%</div></article></div><section class="panel data-panel"><div class="panel-head"><h3>Process performance · <?=h($date)?></h3></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Process</th><th>Records</th><th>Planned</th><th>Actual</th><th>Remaining</th><th>Achievement</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$pct=$r['planned']?min(100,round($r['actual']/$r['planned']*100)):0;?><tr><td><?=h($r['label'])?></td><td><?=$r['records']?></td><td><?=number_format($r['planned'])?></td><td><?=number_format($r['actual'])?></td><td><?=number_format(max(0,$r['planned']-$r['actual']))?></td><td><?=$pct?>%</td><td><a class="btn btn-secondary btn-small" href="production.php?process=<?=h($r['key'])?>&date=<?=h($date)?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></section><p>Live model/part-number CSV: <a href="ModelData.php">Open Data Explorer</a>. CSV polling remains enabled in the existing page.</p></section><?php require __DIR__.'/includes/footer.php'; ?>